<script setup>
import {ref} from 'vue';import {Head,Link} from '@inertiajs/vue3';import axios from 'axios';import {message} from '../art';
const file=ref(null),preview=ref(null),status=ref(''),busy=ref(false);
async function upload(confirm=false){busy.value=true;status.value='';try{const data=new FormData();data.append('backup',file.value);data.append('confirm',confirm?'1':'0');if(preview.value)data.append('preview_hash',preview.value.hash);const r=await axios.post('/import',data);if(confirm){status.value=r.data.message;preview.value=null}else preview.value=r.data.preview}catch(e){status.value=message(e)}finally{busy.value=false}}
</script><template><Head title="Import progress"/><h1>Bring your progress along.</h1><section class="panel"><p>In the offline app, download your progress backup under Sources and progress. Upload that JSON file here to import it into your signed-in account.</p><p>Existing server results are preserved. Imported answers retain completion and bookmarks but do not establish historical first-attempt accuracy or study time.</p><label>Progress backup<input type="file" accept=".json,application/json" @change="file=$event.target.files[0];preview=null"></label><button :disabled="busy||!file" @click="upload(false)">Preview backup</button><div v-if="preview" class="notice"><p>{{preview.completed}} completed questions and {{preview.bookmarks}} bookmarks.</p><button class="primary" :disabled="busy" @click="upload(true)">Import into my account</button></div><p role="status">{{status}}</p><Link href="/progress">View my progress</Link></section></template>
